-- Builds the print commands by replacing the tags of the filetype configuration
local config = require("temp-print.config")
local util = require("temp-print.util")

local M = {}

---Filetype configuration key of each print type
M.CONFIG_KEYS = {
    location = "print_location",
    variable = "print_variable",
    previous_line = "print_previous_line",
    next_line = "print_next_line",
}

---Types regenerated by the auto-update. Variable prints are never updated because the user may need to edit them
M.UPDATABLE = { location = true, previous_line = true, next_line = true }

---Tags with raw, `_escaped` and `_formatted_escaped` variants
local TEXT_TAGS = { "context", "file_path", "var_name", "line_content" }

---@param text string
---@return string
local function identity(text)
    return text
end

---@class TempPrint.RenderValues
---@field context string?
---@field file_path string?
---@field var_name string?
---@field var string?
---@field line string? Printed line (previous/next line prints), before formatting

---Placeholders of a filetype configuration (the filetype ones override the setup ones)
---@param lang_config TempPrint.Config.Lang?
---@return TempPrint.Placeholders
function M.placeholders_of(lang_config)
    return lang_config and lang_config.placeholders or config.options.placeholders
end

---Renders the command of a print type. The `<LINE_NUMBER>` tag is kept, see `set_line_numbers`
---@param type string
---@param lang_config TempPrint.Config.Lang
---@param values TempPrint.RenderValues
---@return string[]? lines
---@return string? error
function M.render(type, lang_config, values)
    local key = M.CONFIG_KEYS[type]
    local print_config = key and lang_config[key]
    if not print_config or not print_config.command then
        return nil, ("the filetype configuration has no '%s.command'"):format(key or type)
    end

    local placeholders = M.placeholders_of(lang_config)
    local escape = lang_config.escape or identity
    local escape_format = lang_config.escape_format or escape

    local texts = {
        context = values.context or "",
        file_path = values.file_path or "",
        var_name = values.var_name or "",
    }
    if values.line then
        local formatter = print_config.formatter or vim.trim
        texts.line_content = formatter(values.line)
    end

    -- The longest variants first. The variable expression is last, so it is never searched for tags
    local command = print_config.command
    for _, name in ipairs(TEXT_TAGS) do
        local text = texts[name] or ""
        command = util.replace_plain(command, placeholders[name .. "_formatted_escaped"], escape_format(text))
    end
    for _, name in ipairs(TEXT_TAGS) do
        command = util.replace_plain(command, placeholders[name .. "_escaped"], escape(texts[name] or ""))
    end
    for _, name in ipairs(TEXT_TAGS) do
        command = util.replace_plain(command, placeholders[name], texts[name] or "")
    end
    command = util.replace_plain(command, placeholders.var, values.var or "")

    return vim.split(command, "\n", { plain = true })
end

---Replaces the `<LINE_NUMBER>` tags. Location and variable prints use the first row of the print (where the statement
---starts, even if a code formatter splits it); line prints use the row of the printed line
---@param type string
---@param lines string[]
---@param first_row integer Row of the first line in the buffer
---@param target_row integer? Row of the printed line (line prints)
---@param lang_config TempPrint.Config.Lang? Configuration with the placeholders
---@return string[]
function M.set_line_numbers(type, lines, first_row, target_row, lang_config)
    local placeholder = M.placeholders_of(lang_config).line_number
    local is_line_print = type == "previous_line" or type == "next_line"
    local row = tostring((is_line_print and target_row or first_row) or 0)
    return vim.tbl_map(function(line)
        return util.replace_plain(line, placeholder, row)
    end, lines)
end

return M
